from pathlib import Path
root=Path('Assets/_Project/Scripts')
def edit(file,a,b):
 p=root/file;s=p.read_text(encoding='utf-8-sig');assert a in s,(file,a);p.write_text(s.replace(a,b),encoding='utf-8')
edit(Path('Data/BuildingData.cs'),'Mill, OilPress, BrewingBarrel, Still','Mill, OilPress, BrewingBarrel, Still,\n        Palisade // 높은 목책. 기존 저장 번호를 유지하도록 끝에 추가.')
edit(Path('Buildings/RuntimeBuildingTemplates.cs'),'BuildingKind.LeafWall => (','BuildingKind.Palisade => ("높은 목책", new Vector3(3, 2.85f, .36f), new Color(.5f, .35f, .2f), 0, 25, 0, 0, 6f, 400f, false),\n                BuildingKind.LeafWall => (')
edit(Path('Buildings/RuntimeBuildingTemplates.cs'),'BuildingKind.LeafWall or BuildingKind.CapWall or BuildingKind.CastleWall =>','BuildingKind.Palisade or BuildingKind.LeafWall or BuildingKind.CapWall or BuildingKind.CastleWall =>')
